static const uint16_t TD5_DTC_DEF_COUNT = sizeof(TD5_DTC_DEFS) / sizeof(TD5_DTC_DEFS[0]);

// Returns the definition for a given X-Y, or nullptr if that bit is undefined.
inline const Td5DtcDef* lookupTd5Dtc(uint8_t x, uint8_t y) {
  for (uint16_t i = 0; i < TD5_DTC_DEF_COUNT; i++) {
    if (TD5_DTC_DEFS[i].x == x && TD5_DTC_DEFS[i].y == y) return &TD5_DTC_DEFS[i];
  }
  return nullptr;
}

